using System.Linq;
using System.Collections.Generic;
using Autodesk.Revit.DB;

var doc = Document;
// setup: floor plan views that are not templates
var plans = new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>()
    .Where(v => !v.IsTemplate && v.ViewType == ViewType.FloorPlan).ToList();
var source  = plans.First(v => v.IsViewValidForTemplateCreation());
var targets = plans.Where(v => v.Id != source.Id).Take(2).ToList();

ElementId tplId = null;
var applied = new List<string>();
// step 1: snapshot the source view's settings into a template, then assign it to the targets
Connector.WithTransaction(doc, () => {
    var tpl = source.CreateViewTemplate();
    tpl.Name = "MCP Standard Floor Plan " + System.Guid.NewGuid().ToString("N").Substring(0, 4);
    tplId = tpl.Id;
    foreach (var t in targets) {
        if (t.IsValidViewTemplate(tplId)) { t.ViewTemplateId = tplId; applied.Add(t.Name); }
    }
});

// verify: the template is a template, and each target now points at it
var tplView = (View)doc.GetElement(tplId);
var assignedNow = targets.Select(t => new { name = t.Name, templateId = ((View)doc.GetElement(t.Id)).ViewTemplateId.ToString() }).ToList();
return new {
    templateId = tplId.ToString(),
    templateName = tplView.Name,
    isTemplate = tplView.IsTemplate,
    source = source.Name,
    targetCount = targets.Count,
    appliedTo = applied,
    assignedNow
};
